import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import DialogBox from "./lib/DialogBox";

/**
 * @since 1.2.1
 * @status beta
 *
 */
@Component({
	tag: "hbr-window",
	styleUrl: "window.scss",
	shadow: true,
})
export class HbrWindow {
	@Element() host: HTMLHbrWindowElement;
	rootRef: HTMLElement;
	headerRef: HTMLElement;
	contentRef: HTMLElement;
	dialogBox: DialogBox;

	/** Indicates whether or not the window is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** The size of the window. mobile: sm, desktop: lg, fullscreen: full */
	@Prop({ reflect: true }) size: "sm" | "lg" | "full" = "lg";

	@Prop({ reflect: true }) placement:
		| "center"
		| "top-left"
		| "top-right"
		| "bottom-left"
		| "bottom-right" = "center";

	/** Emitted when the window opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the window opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the window closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the window closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/**
	 * Emitted when the window opens and the panel gains focus. Calling `event.preventDefault()` will prevent focus and
	 * allow you to set it on a different element in the window, such as an input or button.
	 */
	@Event({ eventName: "hbr-initial-focus" }) hbrInitialFocus: EventEmitter;

	/** show the window */
	@Method()
	async show() {
		if (!this.rootRef) return;
		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			this.open = false;
			return;
		}
		this.open = true;
		this.rootRef.style.display = "block";
		requestAnimationFrame(() => {
			const hbrInitialFocus = this.hbrInitialFocus.emit();
			if (!hbrInitialFocus.defaultPrevented) {
				this.rootRef.focus({ preventScroll: true });
			}
		});
		this.hbrAfterShow.emit();
	}

	/** Hides the modal */
	@Method()
	async hide() {
		if (!this.rootRef) return;
		const hbrHide = this.hbrHide.emit();
		if (hbrHide.defaultPrevented) {
			this.open = true;
			return;
		}

		this.open = false;
		this.rootRef.style.display = "none";
		this.hbrAfterHide.emit();
	}

	@Watch("open")
	handleOpenChange() {
		this.open ? this.show() : this.hide();
	}

	@Watch("size")
	handleSizeChange() {
		if (this.dialogBox) {
			this.dialogBox.size = this.size;
			this.dialogBox.resetSizes();
		}
	}

	@Watch("placement")
	handlePlacementChange() {
		if (this.dialogBox) {
			this.dialogBox.placement = this.placement;
			this.dialogBox.resetSizes();
		}
	}

	componentDidLoad() {
		this.dialogBox = new DialogBox({
			windowRef: this.host,
			rootRef: this.rootRef,
			headerRef: this.headerRef,
			contentRef: this.contentRef,
			size: this.size,
			placement: this.placement,
		});
		// Show on init if open
		if (this.open) {
			this.show();
		}
	}

	render() {
		return (
			<Host
				class={{
					"hbr-css__window--sm": this.size === "sm",
					"hbr-css__window--lg": this.size === "lg",
					"hbr-css__window--full": this.size === "full",
				}}
			>
				<div
					id="dialog"
					class="dialog"
					ref={(el) => {
						this.rootRef = el;
					}}
				>
					<div
						class="titlebar"
						ref={(el) => {
							this.headerRef = el;
						}}
					>
						<span class="titlebar-wrapper" style={{ pointerEvents: "none" }}>
							<slot name="header" />
						</span>
					</div>
					<div
						class="content"
						ref={(el) => {
							this.contentRef = el;
						}}
					>
						<slot />
					</div>
				</div>
			</Host>
		);
	}
}
